    string s;
    cin >> s;
    // b[i] = p[i] - i is non-decreasing; the best common start is its median
    vector<long long> b;
    for (size_t i = 0; i < s.size(); i++)
        if (s[i] == 'R') b.push_back((long long)i - (long long)b.size());
    if (b.empty()) {
        cout << 0 << "\n";
        return 0;
    }
    long long middle = b[b.size() / 2], answer = 0;
    for (long long v : b) answer += llabs(v - middle);
