import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        String s = next();
        // b[i] = p[i] - i is non-decreasing; the best common start is its median
        long[] b = new long[s.length()];
        int count = 0;
        for (int i = 0; i < s.length(); i++)
            if (s.charAt(i) == 'R') {
                b[count] = i - count;
                count++;
            }
        if (count == 0) {
            System.out.println(0);
            return;
        }
        long middle = b[count / 2], answer = 0;
        for (int i = 0; i < count; i++) answer += Math.abs(b[i] - middle);
        System.out.println(answer <= 1000000000L ? answer : -1);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	s := next()
	// b[i] = p[i] - i is non-decreasing; the best common start is its median
	b := []int64{}
	for i, c := range s {
		if c == 'R' {
			b = append(b, int64(i-len(b)))
		}
	}
	if len(b) == 0 {
		fmt.Println(0)
		return
	}
	middle := b[len(b)/2]
	var answer int64
	for _, v := range b {
		if v > middle {
			answer += v - middle
		} else {
			answer += middle - v
		}
	}
	if answer > 1000000000 {
		answer = -1
	}
	fmt.Println(answer)
}
